import 'package:flutter/material.dart';

/// The MoneyTrail app icon (white "M" on MoneyTrail blue), the same image the
/// launcher uses. Generated by tool/gen_brand_assets.py from
/// assets/branding/source/moneytrail-app-icon.png.
class BrandMark extends StatelessWidget {
  const BrandMark({super.key, this.size = 96});
  final double size;

  @override
  Widget build(BuildContext context) => ClipRRect(
    borderRadius: BorderRadius.circular(size * 0.22),
    child: Image.asset(
      'assets/branding/app_icon.png',
      width: size,
      height: size,
      filterQuality: FilterQuality.medium,
      semanticLabel: 'MoneyTrail',
    ),
  );
}
